// clientCoverageProblems compares the routes of the covered features with the
// client tools and the exemptions, and returns one message per problem. It
// takes its inputs as arguments so a test can feed it fake registries.
func clientCoverageProblems(
	registry []auth.RouteFeature,
	tools []ClientToolSpec,
	exemptions map[string]string,
	features []string,
) []string {
	var problems []string
	inRegistry := map[string]bool{}
	for _, r := range registry {
		key := r.Method + " " + r.Pattern
		inRegistry[key] = true
		if !slices.Contains(features, r.Feature) {
			continue
		}
		_, exempt := exemptions[key]
		wrapped := false
		for _, t := range tools {
			if t.Method == r.Method && t.Route == r.Pattern {
				wrapped = true
			}
		}
		if !wrapped && !exempt {
			problems = append(problems, fmt.Sprintf(
				"%s (feature %q) has no client tool and no exemption. Either add a client tool for it "+
					"(a row in ClientTools in clienttools.go, plus the LocalAIClient method, both implementations, "+
					"the tool schema and the localai skill), or add %q to clientToolExemptions in "+
					"clientcoverage_test.go with the reason it is not a tool.", key, r.Feature, key))
		}
	}
	for _, t := range tools {
		key := t.Method + " " + t.Route
		if t.Feature == NoFeature && t.Tool == ToolListModels {
			// list_models reads a listing route that checks no feature, so the
			// route table of the features does not hold it.
			continue
		}
		if !inRegistry[key] {
			problems = append(problems, fmt.Sprintf(
				"client tool %q wraps %s, which is not in auth.RouteFeatureRegistry. The route was removed or renamed: update the tool row.", t.Tool, key))
		}
		if why, ok := exemptions[key]; ok {
			problems = append(problems, fmt.Sprintf(
				"%s is wrapped by client tool %q and also exempt (%q). Keep one: remove the exemption.", key, t.Tool, why))
		}
	}
	for key, why := range exemptions {
		if !inRegistry[key] {
			problems = append(problems, fmt.Sprintf(
				"exemption %q is stale: the route is not in auth.RouteFeatureRegistry. Remove it from clientToolExemptions.", key))
		}
		if strings.TrimSpace(why) == "" {
			problems = append(problems, fmt.Sprintf("exemption %q has no reason. Write why the route is not a client tool.", key))
		}
	}
	sort.Strings(problems)
	return problems
}

// isProjectRoute says whether a registry route belongs to the projects: the
// routes under /api/chats/projects, and the two routes that put a chat in a
// project or pull projects into it. The feature of such a route can be the
// chats feature or the feature of the objects it lists (agents, connectors,
// triggers), so the check goes by the pattern, not by the feature.
func isProjectRoute(pattern string) bool {
	return pattern == "/api/chats/projects" || strings.HasPrefix(pattern, "/api/chats/projects/") ||
		pattern == "/api/chats/:id/project" || pattern == "/api/chats/:id/projects"
}

// projectToolExemptions lists the project routes that deliberately have no
// action of the projects tool, as "METHOD /pattern" -> reason. Sharing is a
// person's act on the folder share and is not a project route.
var projectToolExemptions = map[string]string{}

// projectCoverageProblems returns one message per project route of the
// registry that no action of the projects tool wraps and that has no reason
// to stay without one. It takes its inputs as arguments so a test can feed it
// fake registries.
func projectCoverageProblems(registry []auth.RouteFeature, tools []ClientToolSpec, exemptions map[string]string) []string {
	var problems []string
	seen := map[string]bool{}
	for _, r := range registry {
		key := r.Method + " " + r.Pattern
		if !isProjectRoute(r.Pattern) || seen[key] {
			continue
		}
		seen[key] = true
		wrapped := false
		for _, t := range tools {
			if t.Tool == ToolProjects && t.Method == r.Method && t.Route == r.Pattern {
				wrapped = true
			}
		}
		_, exempt := exemptions[key]
		if !wrapped && !exempt {
			problems = append(problems, fmt.Sprintf(
				"%s (feature %q) is a project route with no action of the projects tool and no exemption. Add an action "+
					"(a row in ClientTools, the case in projects.go, the schema, the localai skill and the docs), or add %q "+
					"to projectToolExemptions in clientcoverage_test.go with the reason.", key, r.Feature, key))
		}
	}
	for key, why := range exemptions {
		if !seen[key] {
			problems = append(problems, fmt.Sprintf("project exemption %q is stale: no such project route in auth.RouteFeatureRegistry. Remove it.", key))
		}
		if strings.TrimSpace(why) == "" {
			problems = append(problems, fmt.Sprintf("project exemption %q has no reason.", key))
		}
	}
	sort.Strings(problems)
	return problems
}

var _ = Describe("Client tool coverage of the project routes", func() {
	It("gives every project route an action of the projects tool or an exemption", func() {
		Expect(clientCoverageProjectsRoutesExist()).To(BeTrue(), "the registry lists project routes")
		Expect(projectCoverageProblems(auth.RouteFeatureRegistry, ClientTools, projectToolExemptions)).To(BeEmpty())
	})

	Describe("the checker", func() {
		registry := []auth.RouteFeature{
			{Method: "GET", Pattern: "/api/chats/projects/:id", Feature: auth.FeatureChats},
			{Method: "GET", Pattern: "/api/chats/projects/:id/agents", Feature: auth.FeatureAgents},
			{Method: "GET", Pattern: "/api/chats/projects/:id/export", Feature: auth.FeatureChats},
			{Method: "PUT", Pattern: "/api/chats/:id/projects", Feature: auth.FeatureChats},
			{Method: "GET", Pattern: "/api/chats/:id", Feature: auth.FeatureChats},
		}
		tools := []ClientToolSpec{
			{Tool: ToolProjects, Method: "GET", Route: "/api/chats/projects/:id"},
			{Tool: ToolProjects, Method: "GET", Route: "/api/chats/projects/:id/agents"},
			{Tool: ToolProjects, Method: "PUT", Route: "/api/chats/:id/projects"},
		}
		It("names a project route with no action, whatever its feature", func() {
			p := projectCoverageProblems(registry, tools, nil)
			Expect(p).To(HaveLen(1))
			Expect(p[0]).To(And(ContainSubstring("GET /api/chats/projects/:id/export"), ContainSubstring("projectToolExemptions")))
		})
		It("accepts an exemption with a reason", func() {
			Expect(projectCoverageProblems(registry, tools, map[string]string{"GET /api/chats/projects/:id/export": "a file download"})).To(BeEmpty())
		})
		It("does not count a row of another tool", func() {
			other := []ClientToolSpec{{Tool: "other", Method: "GET", Route: "/api/chats/projects/:id/export"}}
			p := projectCoverageProblems(registry[2:3], other, nil)
			Expect(p).To(HaveLen(1))
		})
		It("flags a stale exemption and one without a reason", func() {
			p := projectCoverageProblems(registry, append(tools, ClientToolSpec{Tool: ToolProjects, Method: "GET", Route: "/api/chats/projects/:id/export"}),
				map[string]string{"GET /api/chats/projects/gone": "x", "GET /api/chats/projects/:id": " "})
			Expect(p).To(HaveLen(2))
		})
	})
})

func clientCoverageProjectsRoutesExist() bool {
	for _, r := range auth.RouteFeatureRegistry {
		if isProjectRoute(r.Pattern) {
			return true
		}
	}
	return false
}

var _ = Describe("Client tool coverage of the inference routes", func() {
	It("wraps or exempts every inference route in the API route table", func() {
		Expect(clientCoverageProblems(auth.RouteFeatureRegistry, ClientTools, clientToolExemptions, clientCoveredFeatures)).
			To(BeEmpty())
	})

	Describe("the checker", func() {
		registry := []auth.RouteFeature{
			{Method: "POST", Pattern: "/v1/images/generations", Feature: auth.FeatureImages},
			{Method: "POST", Pattern: "/v1/images/new", Feature: auth.FeatureImages},
			{Method: "POST", Pattern: "/api/settings", Feature: auth.FeatureAddons},
		}
		tools := []ClientToolSpec{{Tool: "t", Method: "POST", Route: "/v1/images/generations"}}
		features := []string{auth.FeatureImages}

		It("passes when every route is wrapped or exempt", func() {
			ex := map[string]string{"POST /v1/images/new": "not built yet"}
			Expect(clientCoverageProblems(registry, tools, ex, features)).To(BeEmpty())
		})
		It("names a route with neither a tool nor an exemption, and the fix", func() {
			p := clientCoverageProblems(registry, tools, nil, features)
			Expect(p).To(HaveLen(1))
			Expect(p[0]).To(ContainSubstring("POST /v1/images/new"))
			Expect(p[0]).To(ContainSubstring("add a client tool"))
			Expect(p[0]).To(ContainSubstring("clientToolExemptions"))
		})
		It("ignores routes of other features", func() {
			Expect(clientCoverageProblems(registry, tools, map[string]string{"POST /v1/images/new": "x"}, features)).To(BeEmpty())
		})
		It("flags a stale exemption", func() {
			ex := map[string]string{"POST /v1/images/new": "x", "POST /gone": "x"}
			p := clientCoverageProblems(registry, tools, ex, features)
			Expect(p).To(HaveLen(1))
			Expect(p[0]).To(ContainSubstring("exemption \"POST /gone\" is stale"))
		})
		It("flags a tool route that left the registry", func() {
			gone := append([]ClientToolSpec{}, tools...)
			gone = append(gone, ClientToolSpec{Tool: "old", Method: "POST", Route: "/v1/removed"})
			ex := map[string]string{"POST /v1/images/new": "x"}
			p := clientCoverageProblems(registry, gone, ex, features)
			Expect(p).To(HaveLen(1))
			Expect(p[0]).To(ContainSubstring("not in auth.RouteFeatureRegistry"))
		})
		It("flags a route that is both wrapped and exempt", func() {
			ex := map[string]string{"POST /v1/images/new": "x", "POST /v1/images/generations": "x"}
			p := clientCoverageProblems(registry, tools, ex, features)
			Expect(p).To(HaveLen(1))
			Expect(p[0]).To(ContainSubstring("also exempt"))
		})
		It("flags an exemption without a reason", func() {
			p := clientCoverageProblems(registry, tools, map[string]string{"POST /v1/images/new": " "}, features)
			Expect(p).To(HaveLen(1))
			Expect(p[0]).To(ContainSubstring("has no reason"))
		})
	})
})

package localaitools

import (
	"encoding/json"
	"slices"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

// clientBudgetBytes bounds the tools/list entries of the client group (name,
// description and input schema of every tool, as JSON).
//
// Every tool of an always-sent group is paid on every turn of every chat, by
// every user, whether or not the turn needs it. On a small context window
// that cost decides whether the chat fits at all. The value is the measured
// size after the merges and trims (6,948 bytes, about 1,750 tokens) plus
// about 1%: the voice_profile tool took 613 bytes of the 5,910 before it. Raise
// it only with a reason in the commit message: a new tool must justify its place first, and
// an operation that shares state with an existing tool belongs in that tool
// as an action (see .agents/localai-assistant-mcp.md).
//
// 6,600 to 7,000: list_models (345 bytes). Without it a user who is not an
// administrator cannot learn the names of the models the other tools take,
// and guesses them. It is the one listing tool for every user, so it is not
// a candidate for a merge: it shares no state with a generation tool.
//
// 7,000 to 7,300: generate_image takes seed, an init image and reference
// images (about 240 bytes). They are arguments of the one image route the API
// already has, so they cost no new tool.
//
// 7,300 to 8,000: generate_video reads what the /video route reads and the
// tool did not send: end_image, audio, ref_images, ref_videos, ref_audios,
// seed, cfg_scale, steps (about 700 bytes). ref_videos is a list of frame
// lists because that is how the route takes a video.
//
// 8,000 to 8,550: generate_sound takes the ten fields of the route that a
// song model reads: caption, bpm, keyscale, timesignature, language,
// vocal_language, think, do_sample, prompt_influence, expansion_model (about
// 480 bytes).
//
// 8,550 to 8,650: speak takes sample_rate, which the TTS route reads (about
// 60 bytes).
//
// 8,650 to 8,900: voice_profile create takes description and extra_clips,
// because the API takes up to ten clips and a description (about 210 bytes).
//
// 8,900 to 9,250: detect takes points and boxes (segmentation prompts), and
// voice and face take anti_spoofing for verify (about 340 bytes together).
// All three are fields their routes read.
//
// 9,250 to 9,700: upscale_image (401 bytes) and transform_audio (690 bytes).
// Each is its own route and model use case; neither shares state with an
// existing tool. transform_audio is one flat schema with a single
// allow-listed params map instead of a field per backend key. The argument
// descriptions of the whole group were shortened in the same change (the
// group would be 10,289 bytes without that); no argument was removed. The
// group measures 9,651 bytes. Upscaling and transform are not merge
// candidates, and the tool search can defer the group on a small window.
//
// 9,700 to 9,900: the offset, limit and query arguments of list_models. They
// let the model page through a long model list and search it by name; the
// group measures 9,879 bytes.
//
// 9,900 to 10,600: the projects tool (657 bytes), ten actions in one flat
// schema (list, get, create, update, archive, restore, delete,
// set_chat_project, pull, unpull) that share one domain, the user's projects.
// It is not a media tool and has no model: it is the way a client or an agent
// manages projects without a person at the Projects page. Every action is an
// action, not a tool, and the group measures 10,536 bytes. The tool search can
// defer the group on a small window.
//
// 10,600 to 10,700: the actions connections, triggers and loops of the projects
// tool (about 65 bytes: three names in the enum and in the argument text), the
// three reads of what is bound to the agents of a project; the group measures
// 10,647 bytes.
//
// 10,700 to 11,000: the actions memory, write_memory, chats and shared_get of
// the projects tool (about 285 bytes: four names in the enum, the argument
// text and the two arguments file and content). They close the gap between
// the project routes and the tool: read and write the memory of a project,
// list its chats, and read a shared project with its memory. They share the
// one domain of the tool, so they are actions and not tools; the group
// measures 10,986 bytes.
//
// 11,000 to 11,250: the attached argument of the projects tool (about 215
// bytes: the name and a map of lists). It is what a project owns, in the shape
// of its defaults, so the model can read and set the tools that its chats and
// agents get; it shares the one domain of the tool; the group measures 11,202
// bytes.
const clientBudgetBytes = 11250

var _ = Describe("Client tool surface", func() {
	It("stays inside the byte budget of an always-sent group", func() {
		ctx, sess, done := connectInMemory(&fakeClient{}, Options{})
		DeferCleanup(done)
		res, err := sess.ListTools(ctx, nil)
		Expect(err).ToNot(HaveOccurred())
		total := 0
		for _, t := range res.Tools {
			if ToolGroupOf(t.Name) != GroupClient {
				continue
			}
			raw, err := json.Marshal(t)
			Expect(err).ToNot(HaveOccurred())
			total += len(raw)
		}
		GinkgoWriter.Printf("client group: %d bytes (budget %d)\n", total, clientBudgetBytes)
		Expect(total).To(BeNumerically("<=", clientBudgetBytes),
			"the client group grew past its budget; merge or trim before raising it")
	})

	It("keeps the action tools flat, with an action enum and no oneOf or anyOf", func() {
		ctx, sess, done := connectInMemory(&fakeClient{}, Options{})
		DeferCleanup(done)
		res, err := sess.ListTools(ctx, nil)
		Expect(err).ToNot(HaveOccurred())
		seen := 0
		for _, t := range res.Tools {
			if t.Name != ToolVoice && t.Name != ToolFace && t.Name != ToolVoiceProfile && t.Name != ToolProjects {
				continue
			}
			seen++
			raw, _ := json.Marshal(t.InputSchema)
			var m map[string]any
			Expect(json.Unmarshal(raw, &m)).To(Succeed())
			Expect(m).ToNot(HaveKey("oneOf"), t.Name)
			Expect(m).ToNot(HaveKey("anyOf"), t.Name)
			Expect(m["type"]).To(Equal("object"))
			action := m["properties"].(map[string]any)["action"].(map[string]any)
			switch t.Name {
			case ToolVoiceProfile:
				Expect(action["enum"]).To(ConsistOf("create", "list", "delete"))
			case ToolProjects:
				Expect(action["enum"]).To(ConsistOf("list", "get", "create", "update", "archive", "restore", "delete", "set_chat_project", "pull", "unpull", "agents", "connections", "triggers", "loops", "shared", "shared_get", "memory", "write_memory", "chats"))
				// Sharing is never a tool: only the human session of the folder
				// share API grants or revokes access.
				for _, a := range action["enum"].([]any) {
					Expect(a).NotTo(MatchRegexp(`^(share|unshare|grant|revoke|set_share|edit_share|share_project)$`), "no action may share a project")
					Expect(a).To(BeElementOf("list", "get", "create", "update", "archive", "restore", "delete", "set_chat_project", "pull", "unpull", "agents", "connections", "triggers", "loops", "shared", "shared_get", "memory", "write_memory", "chats"))
				}
			default:
				Expect(action["enum"]).To(ConsistOf("verify", "identify"))
			}
			Expect(m["required"]).To(ContainElement("action"))
		}
		Expect(seen).To(Equal(4))
	})

	It("keeps all fourteen projects actions on the MCP path: the in-chat gate is on the chat side only", func() {
		for _, args := range []map[string]any{
			{"action": "pull", "chat_id": "c", "project": "p"}, {"action": "unpull", "chat_id": "c", "project": "p"},
			{"action": "set_chat_project", "chat_id": "c", "project": "p"}, {"action": "delete", "project": "p"},
		} {
			fc := &fakeClient{}
			ctx, sess, done := connectInMemory(fc, Options{})
			DeferCleanup(done)
			res := callTool(ctx, sess, ToolProjects, args)
			Expect(res.IsError).To(BeFalse(), resultText(res))
			Expect(fc.recorded()).To(HaveLen(1))
		}
	})

	It("keeps agents, and only the reading actions, in the read-only flavour", func() {
		fc := &fakeClient{}
		ctx, sess, done := connectInMemory(fc, Options{DisableMutating: true})
		DeferCleanup(done)
		res := callTool(ctx, sess, ToolProjects, map[string]any{"action": "agents", "project": "p"})
		Expect(res.IsError).To(BeFalse(), resultText(res))
		Expect(fc.recorded()).To(HaveLen(1))
		for i, a := range []string{"connections", "triggers", "loops", "shared"} {
			res = callTool(ctx, sess, ToolProjects, map[string]any{"action": a, "project": "p"})
			Expect(res.IsError).To(BeFalse(), resultText(res))
			Expect(fc.recorded()).To(HaveLen(i + 2))
		}
		res = callTool(ctx, sess, ToolProjects, map[string]any{"action": "delete", "project": "p"})
		Expect(res.IsError).To(BeTrue())
		Expect(fc.recorded()).To(HaveLen(5))
		res = callTool(ctx, sess, ToolProjects, map[string]any{"action": "share", "project": "p"})
		Expect(res.IsError).To(BeTrue())
		Expect(fc.recorded()).To(HaveLen(5), "there is no action that shares a project")
	})

	It("has no edit_image, verify_* or identify_* tool any more", func() {
		ctx, sess, done := connectInMemory(&fakeClient{}, Options{})
		DeferCleanup(done)
		names := listToolNames(ctx, sess)
		for _, gone := range []string{"edit_image", "verify_voice", "identify_voice", "verify_face", "identify_face"} {
			Expect(slices.Contains(names, gone)).To(BeFalse(), gone)
		}
	})

	Describe("generate_image", func() {
		It("makes a new image without image and mask", func() {
			fc := &fakeClient{}
			ctx, sess, done := connectInMemory(fc, Options{})
			DeferCleanup(done)
			res := callTool(ctx, sess, ToolGenerateImage, map[string]any{"prompt": "a fox", "n": 2})
			Expect(res.IsError).To(BeFalse(), resultText(res))
			calls := fc.recorded()
			Expect(calls).To(HaveLen(1))
			Expect(calls[0].method).To(Equal("GenerateImage"))
			Expect(calls[0].args.(GenerateImageRequest).N).To(Equal(2))
		})

		It("repaints with image and mask", func() {
			fc := &fakeClient{}
			ctx, sess, done := connectInMemory(fc, Options{})
			DeferCleanup(done)
			res := callTool(ctx, sess, ToolGenerateImage, map[string]any{"prompt": "a hat", "image": "a.png", "mask": "m.png", "steps": 5})
			Expect(res.IsError).To(BeFalse(), resultText(res))
			calls := fc.recorded()
			Expect(calls).To(HaveLen(1))
			Expect(calls[0].method).To(Equal("EditImage"))
			Expect(calls[0].args).To(Equal(EditImageRequest{Prompt: "a hat", Image: "a.png", Mask: "m.png", Steps: 5}))
		})

		It("starts from an image without a mask (img2img) and passes seed and references", func() {
			fc := &fakeClient{}
			ctx, sess, done := connectInMemory(fc, Options{})
			DeferCleanup(done)
			res := callTool(ctx, sess, ToolGenerateImage, map[string]any{"prompt": "x", "image": "a.png", "seed": 7, "ref_images": []string{"r1.png", "r2.png"}})
			Expect(res.IsError).To(BeFalse(), resultText(res))
			calls := fc.recorded()
			Expect(calls).To(HaveLen(1))
			Expect(calls[0].method).To(Equal("GenerateImage"))
			seed := 7
			Expect(calls[0].args).To(Equal(GenerateImageRequest{Prompt: "x", Image: "a.png", Seed: &seed, RefImages: []string{"r1.png", "r2.png"}}))
		})

		It("refuses a mask without an image, and a seed or references with a mask, and calls nothing", func() {
			fc := &fakeClient{}
			ctx, sess, done := connectInMemory(fc, Options{})
			DeferCleanup(done)
			res := callTool(ctx, sess, ToolGenerateImage, map[string]any{"prompt": "x", "image": "a.png", "mask": "m.png", "seed": 1})
			Expect(res.IsError).To(BeTrue())
			Expect(resultText(res)).To(ContainSubstring("do not work with mask"))
			res = callTool(ctx, sess, ToolGenerateImage, map[string]any{"prompt": "x", "mask": "m.png"})
			Expect(res.IsError).To(BeTrue())
			Expect(resultText(res)).To(ContainSubstring("mask needs image"))
			Expect(fc.recorded()).To(BeEmpty())
		})
	})

	DescribeTable("the action tools check the fields of each action",
		func(tool string, args map[string]any, method string, wantErr string) {
			fc := &fakeClient{}
			ctx, sess, done := connectInMemory(fc, Options{})
			DeferCleanup(done)
			res := callTool(ctx, sess, tool, args)
			if wantErr != "" {
				Expect(res.IsError).To(BeTrue(), resultText(res))
				Expect(resultText(res)).To(ContainSubstring(wantErr))
				Expect(fc.recorded()).To(BeEmpty())
				return
			}
			Expect(res.IsError).To(BeFalse(), resultText(res))
			Expect(fc.recorded()).To(HaveLen(1))
			Expect(fc.recorded()[0].method).To(Equal(method))
		},
		Entry("voice verify", ToolVoice, map[string]any{"action": "verify", "audio": "a.wav", "audio2": "b.wav"}, "VerifyVoice", ""),
		Entry("voice identify", ToolVoice, map[string]any{"action": "identify", "audio": "a.wav", "top_k": 3}, "IdentifyVoice", ""),
		Entry("voice verify without audio2", ToolVoice, map[string]any{"action": "verify", "audio": "a.wav"}, "", `voice: action "verify" needs audio2`),
		Entry("voice identify without audio", ToolVoice, map[string]any{"action": "identify", "audio": ""}, "", `voice: action "identify" needs audio`),
		Entry("voice with no action", ToolVoice, map[string]any{"audio": "a.wav"}, "", "action"),
		Entry("voice with a bad action", ToolVoice, map[string]any{"action": "clone", "audio": "a.wav"}, "", "does not equal any of"),
		Entry("face verify", ToolFace, map[string]any{"action": "verify", "image": "a.png", "image2": "b.png"}, "VerifyFace", ""),
		Entry("face identify", ToolFace, map[string]any{"action": "identify", "image": "a.png"}, "IdentifyFace", ""),
		Entry("face verify without image2", ToolFace, map[string]any{"action": "verify", "image": "a.png"}, "", `face: action "verify" needs image2`),
		Entry("voice_profile create without a name", ToolVoiceProfile, map[string]any{"action": "create", "audio": "a.wav", "transcript": "x"}, "", `voice_profile: action "create" needs name`),
		Entry("voice_profile create without audio", ToolVoiceProfile, map[string]any{"action": "create", "name": "n", "transcript": "x"}, "", `voice_profile: action "create" needs audio`),
		Entry("voice_profile create without a transcript", ToolVoiceProfile, map[string]any{"action": "create", "name": "n", "audio": "a.wav"}, "", `voice_profile: action "create" needs transcript`),
		Entry("voice_profile create", ToolVoiceProfile, map[string]any{"action": "create", "name": "n", "audio": "a.wav", "transcript": "x"}, "CreateVoiceProfile", ""),
		Entry("voice_profile list", ToolVoiceProfile, map[string]any{"action": "list"}, "ListVoiceProfiles", ""),
		Entry("voice_profile delete without id", ToolVoiceProfile, map[string]any{"action": "delete"}, "", `voice_profile: action "delete" needs id`),
		Entry("voice_profile delete", ToolVoiceProfile, map[string]any{"action": "delete", "id": "abc"}, "DeleteVoiceProfile", ""),
		Entry("voice_profile with a bad action", ToolVoiceProfile, map[string]any{"action": "update"}, "", "does not equal any of"),
		Entry("projects list", ToolProjects, map[string]any{"action": "list"}, "Projects", ""),
		Entry("projects get", ToolProjects, map[string]any{"action": "get", "project": "p1"}, "Projects", ""),
		Entry("projects get without a project", ToolProjects, map[string]any{"action": "get"}, "", `projects: action "get" needs project`),
		Entry("projects create", ToolProjects, map[string]any{"action": "create", "name": "Acme"}, "Projects", ""),
		Entry("projects create without a name", ToolProjects, map[string]any{"action": "create"}, "", `projects: action "create" needs name`),
		Entry("projects update", ToolProjects, map[string]any{"action": "update", "project": "p1", "name": "New"}, "Projects", ""),
		Entry("projects update that clears the description", ToolProjects, map[string]any{"action": "update", "project": "p1", "description": ""}, "Projects", ""),
		Entry("projects update with nothing to change", ToolProjects, map[string]any{"action": "update", "project": "p1"}, "", `projects: action "update" needs name, description or attached`),
		Entry("projects archive", ToolProjects, map[string]any{"action": "archive", "project": "p1"}, "Projects", ""),
		Entry("projects restore", ToolProjects, map[string]any{"action": "restore", "project": "p1"}, "Projects", ""),
		Entry("projects delete", ToolProjects, map[string]any{"action": "delete", "project": "p1"}, "Projects", ""),
		Entry("projects delete without a project", ToolProjects, map[string]any{"action": "delete"}, "", `projects: action "delete" needs project`),
		Entry("projects set_chat_project", ToolProjects, map[string]any{"action": "set_chat_project", "chat_id": "c1", "project": "p1"}, "Projects", ""),
		Entry("projects set_chat_project with no project takes the chat out", ToolProjects, map[string]any{"action": "set_chat_project", "chat_id": "c1"}, "Projects", ""),
		Entry("projects set_chat_project without a chat", ToolProjects, map[string]any{"action": "set_chat_project", "project": "p1"}, "", `projects: action "set_chat_project" needs chat_id`),
		Entry("projects pull", ToolProjects, map[string]any{"action": "pull", "chat_id": "c1", "project": "p1"}, "Projects", ""),
		Entry("projects pull without a project", ToolProjects, map[string]any{"action": "pull", "chat_id": "c1"}, "", `projects: action "pull" needs project`),
		Entry("projects unpull", ToolProjects, map[string]any{"action": "unpull", "chat_id": "c1", "project": "p1"}, "Projects", ""),
		Entry("projects with a bad action", ToolProjects, map[string]any{"action": "purge"}, "", "does not equal any of"),
		Entry("face with a bad action", ToolFace, map[string]any{"action": "x", "image": "a.png"}, "", "does not equal any of"),
	)

	It("tells the model that a profile of an administrator is visible to all", func() {
		ctx, sess, done := connectInMemory(&fakeClient{}, Options{})
		DeferCleanup(done)
		res := callTool(ctx, sess, ToolVoiceProfile, map[string]any{"action": "list"})
		Expect(res.IsError).To(BeFalse(), resultText(res))
		Expect(resultText(res)).To(ContainSubstring("created by an administrator are visible to all users"))
	})
})

package localaitools

import (
	"encoding/json"
	"slices"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"

	"github.com/mudler/LocalAI/core/http/auth"
)

// clientToolNames lists the names in ClientTools.
func clientToolNames() []string {
	var out []string
	for _, s := range ClientTools {
		if !slices.Contains(out, s.Tool) {
			out = append(out, s.Tool)
		}
	}
	return out
}

var _ = Describe("Client tool table", func() {
	It("has an entry with a route, a feature and a model flag for every client tool", func() {
		want := []string{
			ToolGenerateImage, ToolSpeak, ToolTranscribeAudio, ToolDescribeImage, ToolEmbed,
			ToolDetect, ToolRerank, ToolGenerateVideo, ToolGenerateSound, ToolUpscaleImage, ToolTransformAudio,
			ToolVoice, ToolFace, ToolVoiceProfile, ToolListModels, ToolProjects,
		}
		Expect(clientToolNames()).To(ConsistOf(want))
		for _, s := range ClientTools {
			Expect(s.Route).To(HavePrefix("/"), s.Tool)
			Expect(s.Method).To(BeElementOf("GET", "POST", "DELETE", "PATCH", "PUT"), s.Tool)
			if s.Tool != ToolVoiceProfile && s.Tool != ToolListModels && s.Tool != ToolProjects {
				// voice_profile, list_models and projects manage or read data and need no model.
				Expect(s.Method).To(Equal("POST"), s.Tool)
				Expect(s.Flag).ToNot(BeZero(), s.Tool)
			}
			Expect(s.Capability).ToNot(BeEmpty(), s.Tool)
		}
	})

	It("names a feature that exists, and the API route checks that same feature", func() {
		for _, s := range ClientTools {
			if s.Feature == NoFeature {
				// list_models: the route checks no feature (the model
				// allow-list filters its answer).
				Expect(s.Tool).To(Equal(ToolListModels))
				continue
			}
			Expect(auth.AllFeatures).To(ContainElement(s.Feature), "%s: unknown feature %q", s.Tool, s.Feature)
			found := false
			for _, r := range auth.RouteFeatureRegistry {
				// A client row (client_inference) is another way in for a
				// client key; the user feature is the one the tool names.
				if r.Method == s.Method && r.Pattern == s.Route && !auth.IsClientFeature(r.Feature) {
					found = true
					Expect(r.Feature).To(Equal(s.Feature), "%s: %s %s checks another feature", s.Tool, s.Method, s.Route)
				}
			}
			Expect(found).To(BeTrue(), "%s: %s %s is not in auth.RouteFeatureRegistry", s.Tool, s.Method, s.Route)
		}
	})

	It("carries the projects routes as rows of the projects tool, on the chats feature (the lists of agents, connections and triggers on their own), with no model", func() {
		// Decision (see .agents/localai-assistant-mcp.md): the client group may
		// carry per-user routes that are not inference, as voice_profile does.
		// The projects routes are of the chats feature, which clientCoveredFeatures
		// does not list (that is the feature of the chat itself, not of the studio),
		// so no row of this table is forced by the coverage test; the rows are here
		// because the tool acts as the calling user.
		want := map[string]string{
			ActionList: "GET /api/chats/projects", ActionGet: "GET /api/chats/projects/:id",
			ActionCreate: "POST /api/chats/projects", ActionUpdate: "PATCH /api/chats/projects/:id",
			ActionArchive: "POST /api/chats/projects/:id/archive", ActionRestore: "POST /api/chats/projects/:id/restore",
			ActionDelete: "DELETE /api/chats/projects/:id", ActionSetChatProject: "PUT /api/chats/:id/project",
			ActionPull: "PUT /api/chats/:id/projects", ActionUnpull: "PUT /api/chats/:id/projects",
			ActionAgents:      "GET /api/chats/projects/:id/agents",
			ActionConnections: "GET /api/chats/projects/:id/connections", ActionTriggers: "GET /api/chats/projects/:id/triggers",
			ActionLoops: "GET /api/chats/projects/:id/loops", ActionShared: "GET /api/chats/projects/shared",
			ActionSharedGet: "GET /api/chats/projects/shared/:ref", actionSharedMemory: "GET /api/chats/projects/shared/:ref/memory",
			ActionMemory: "GET /api/chats/projects/:id/memory", ActionWriteMemory: "PUT /api/chats/projects/:id/memory/:file",
			ActionChats: "GET /api/chats/projects/:id/chats",
		}
		// The three lists show objects of another feature: the registry gates
		// them by that feature, and the row says the same.
		feature := map[string]string{ActionAgents: auth.FeatureAgents, ActionConnections: auth.FeatureConnectors, ActionTriggers: auth.FeatureTriggers}
		for action, route := range want {
			s := clientSpecAction(ToolProjects, action)
			Expect(s.Tool).To(Equal(ToolProjects), action)
			Expect(s.Method+" "+s.Route).To(Equal(route), action)
			if f, ok := feature[action]; ok {
				Expect(s.Feature).To(Equal(f), action)
			} else {
				Expect(s.Feature).To(Equal(auth.FeatureChats), action)
			}
			Expect(s.Flag).To(BeZero(), action)
		}
		Expect(ToolGroupOf(ToolProjects)).To(Equal(GroupClient))
	})

	It("tells client tools from manage tools", func() {
		for _, name := range clientToolNames() {
			Expect(ToolGroupOf(name)).To(Equal(GroupClient), name)
			Expect(ToolGroups()[name]).To(Equal(GroupClient), name)
		}
		for _, name := range mutatingToolNames {
			Expect(ToolGroupOf(name)).To(Equal(GroupManage), name)
		}
		Expect(ToolGroupOf(ToolListNodes)).To(Equal(GroupManage))
	})

	It("registers every client tool by default", func() {
		ctx, sess, done := connectInMemory(&fakeClient{}, Options{})
		defer done()
		names := listToolNames(ctx, sess)
		for _, n := range clientToolNames() {
			Expect(slices.Contains(names, n)).To(BeTrue(), "%s missing", n)
		}
	})

	It("registers no client tool that writes files or makes content in the read-only flavour", func() {
		ctx, sess, done := connectInMemory(&fakeClient{}, Options{DisableMutating: true})
		defer done()
		names := listToolNames(ctx, sess)
		for _, n := range []string{ToolGenerateImage, ToolSpeak, ToolEmbed, ToolGenerateVideo, ToolGenerateSound, ToolUpscaleImage, ToolTransformAudio} {
			Expect(names).NotTo(ContainElement(n))
		}
		Expect(names).To(ContainElements(ToolTranscribeAudio, ToolDescribeImage, ToolRerank, ToolVoiceProfile, ToolListModels, ToolProjects))
		// voice_profile and projects keep only the actions that read.
		res, err := sess.ListTools(ctx, nil)
		Expect(err).NotTo(HaveOccurred())
		for _, t := range res.Tools {
			if t.Name == ToolProjects {
				schema, _ := json.Marshal(t.InputSchema)
				Expect(string(schema)).To(ContainSubstring(`"list"`))
				Expect(string(schema)).To(ContainSubstring(`"get"`))
				for _, w := range []string{"create", "update", "archive", "restore", "delete", "set_chat_project", "pull", "unpull"} {
					Expect(string(schema)).NotTo(ContainSubstring(`"` + w + `"`))
				}
			}
			if t.Name == ToolVoiceProfile {
				schema, _ := json.Marshal(t.InputSchema)
				Expect(string(schema)).To(ContainSubstring(`"list"`))
				Expect(string(schema)).NotTo(ContainSubstring(`"create"`))
				Expect(string(schema)).NotTo(ContainSubstring(`"delete"`))
			}
		}
	})

	It("registers no client tool that needs files when there is no files folder", func() {
		ctx, sess, done := connectInMemory(&fakeClient{}, Options{DisableClientFiles: true})
		defer done()
		names := listToolNames(ctx, sess)
		for n := range clientToolFiles {
			Expect(names).NotTo(ContainElement(n))
		}
		Expect(names).To(ContainElements(ToolRerank, ToolVoiceProfile, ToolListModels, ToolProjects))
	})

	It("keeps list_models in the client group, and list_installed_models in the manage group", func() {
		Expect(ToolGroupOf(ToolListModels)).To(Equal(GroupClient))
		Expect(ToolGroupOf(ToolListInstalledModels)).To(Equal(GroupManage))
	})
})

package localaitools

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

// The OAuth routes of the connections (/api/chats/connectors/.../oauth and
// /api/chats/admin/oauth-clients) carry a client secret, a login's state and
// the approval of an add-on's login. A secret must not pass through a chat,
// and a login is a person's act in their own browser, so no MCP tool maps to
// them and nothing in this package calls them. The two administrator routes
// are listed in adminRoutesWithoutTool with that reason.
var _ = Describe("OAuth logins of connections and the MCP tools", func() {
	It("maps no tool to an OAuth route", func() {
		for tool, route := range toolToHTTPRoute {
			Expect(route).NotTo(ContainSubstring("/oauth"), tool)
			Expect(route).NotTo(ContainSubstring("oauth-clients"), tool)
		}
		for _, route := range []string{"GET /api/chats/admin/oauth-clients/:addonId", "PUT /api/chats/admin/oauth-clients/:addonId"} {
			Expect(adminRoutesWithoutTool).To(HaveKey(route))
		}
	})

	It("never names the routes in the code of the MCP server, its clients or its prompts", func() {
		var hits []string
		Expect(filepath.Walk(".", func(path string, info os.FileInfo, err error) error {
			if err != nil || info.IsDir() || strings.HasSuffix(path, "_test.go") {
				return err
			}
			b, rerr := os.ReadFile(path)
			if rerr != nil {
				return rerr
			}
			// A compiled test binary (ginkgo leaves <package>.test here) holds
			// the strings of the test files; only text sources count.
			if bytes.IndexByte(b, 0) >= 0 {
				return nil
			}
			s := strings.ToLower(string(b))
			if strings.Contains(s, "oauth-clients") || strings.Contains(s, "connectors/oauth") || strings.Contains(s, "/oauth/start") || strings.Contains(s, "/oauth/disconnect") {
				hits = append(hits, path)
			}
			return nil
		})).To(Succeed())
		Expect(hits).To(BeEmpty(), "an MCP tool or client must not reach the OAuth routes of the connections")
	})
})

